head.script:
scwin.onpageload = function () {
	//$p.executeSubmission("submission1");

	var dataJson = [
		{ "col1": "101", "col2": "201", "col3": "301" },
		{ "col1": "102", "col2": "202", "col3": "302" },
		{ "col1": "103", "col2": "203", "col3": "303" },
		{ "col1": "104", "col2": "204", "col3": "304" },
		{ "col1": "105", "col2": "205", "col3": "305" }
	]
	dataList1.setJSON(dataJson);

	var obj = {
		"nodeset": "data:dataList1",
		"label": "col1",
		"value": "col2",
		"visibleRowNum" : 10,
		"width": 400,
		"height": 300,
		"item": [{ "ref": "col1", "header": "col1" }, { "ref": "col2", "header": "col2" }, { "ref": "col3", "header": "col3" }]
	}
	autoComplete1.setGridItemset(obj)
};

scwin.onpageunload = function () {

};

scwin.setData = function () {
	$p.executeSubmission("submission1");
}

	scwin.checkVal1 = function() {
		var log = WebSquare.logger.getLog();
		return log.indexOf("setRowVisible error") < 0;		
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_gridViewItemTable_gridView_cell_1_0').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
